changeSet.sql:
CREATE TABLE authorities (
    id          UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name        TEXT NOT NULL,
    bio         TEXT,
    era         TEXT,
    madhab      TEXT,
    metadata    JSONB,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_authorities_name          ON authorities(name);
CREATE INDEX idx_authorities_era           ON authorities(era);
CREATE INDEX idx_authorities_madhab        ON authorities(madhab);
CREATE INDEX idx_authorities_metadata_gin  ON authorities USING GIN (metadata);
